script:
(function () {
  'use strict';
  // Cash back rebate (at the standard rate) versus a promotional low rate (no rebate).
  //   Taxable = price - trade-in credit (- rebate when the rebate-tax box is ticked), never below 0.
  //   Loan = price - rebate (rebate offer only) - down - trade-in + owed (+ tax and fees if financed).
  //   Payment: M = L * i / (1 - (1 + i)^-n), i = rate / 12 (M = L / n at 0%).
  //   Total cost = price - rebate + sales tax + fees + total interest (same cash-flow basis for both).
  //   Break-even rate: the standard rate at which both totals are equal, found by bisection.
  // Verified in Node (scratchpad tests/w2loans): $50,000 car, $1,000 rebate, 5% vs 2% for 60 months,
  //   $10,000 down, 7% tax, $2,000 fees paid upfront -> $735.98/mo and $59,658.69 total with the
  //   rebate, $701.11/mo and $57,566.62 with the low rate (matches a published calculator's default);
  //   at the break-even rate (rounded to 0.01%) the totals agree within ; no NaN on blank or negative input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });

  function el(id) { return document.getElementById(id); }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function monthlyPayment(principal, annualRate, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualRate / 12;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  function offer(o, rebate, ratePct) {
    var taxable = Math.max(0, o.price - (o.tradeCredit ? o.trade : 0) - (o.rebateTax ? rebate : 0));
    var tax = taxable * o.taxRate / 100;
    var loan = Math.max(0, o.price - rebate - o.down - o.trade + o.owed + (o.finance ? tax + o.fees : 0));
    var pmt = monthlyPayment(loan, ratePct / 100, o.months);
    var interest = Math.max(0, pmt * o.months - loan);
    return { loan: loan, tax: tax, pmt: pmt, interest: interest, paid: pmt * o.months,
             upfront: o.down + (o.finance ? 0 : tax + o.fees), total: o.price - rebate + tax + o.fees + interest };
  }

  // Standard rate at which the rebate offer costs exactly as much as the low-rate offer.
  function breakEven(o) {
    var target = offer(o, 0, o.low).total;
    var f = function (r) { return offer(o, o.rebate, r).total - target; };
    if (f(0) >= 0) return NaN;
    var lo = 0, hi = 100;
    if (f(hi) < 0) return Infinity;
    for (var k = 0; k < 100; k++) {
      var mid = (lo + hi) / 2;
      if (f(mid) < 0) lo = mid; else hi = mid;
    }
    return (lo + hi) / 2;
  }

  function setText(id, text) { el(id).textContent = text; }

  function rateText(v) { return String(Number(v.toFixed(3))) + '%'; }

  function clearResults() {
    setText('cbVerdictTitle', '–'); setText('cbVerdict', '');
    setText('cbSaving', '–'); setText('cbBreakEven', '–');
    el('cbTable').innerHTML = '';
  }

  function update() {
    var o = {
      price: read('cbPrice'), rebate: read('cbRebate', true), months: read('cbTerm'), high: read('cbHigh'), low: read('cbLow'),
      down: read('cbDown', true), taxRate: read('cbTaxRate', true), fees: read('cbFees', true), trade: read('cbTrade', true),
      owed: read('cbOwed', true), finance: el('cbFinanceCosts').checked, tradeCredit: el('cbTradeCredit').checked,
      rebateTax: el('cbRebateTax').checked
    };
    var error = el('cbError'), msg = '';
    if (isNaN(o.price) || o.price <= 0) msg = 'Enter a vehicle price greater than $0.';
    else if (isNaN(o.months) || o.months < 1 || o.months > 96 || o.months % 1 !== 0) msg = 'Enter a loan term of 1 to 96 whole months.';
    else if (isNaN(o.high) || isNaN(o.low) || o.high < 0 || o.low < 0 || o.high > 40 || o.low > 40) msg = 'Enter both interest rates from 0% to 40%.';
    else if ([o.rebate, o.down, o.taxRate, o.fees, o.trade, o.owed].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Amounts and rates cannot be negative.';
    else if (o.taxRate > 20) msg = 'Enter a sales tax rate of 20% or less.';
    else if (o.rebate >= o.price) msg = 'The rebate must be less than the vehicle price.';
    var a, b;
    if (!msg) {
      a = offer(o, o.rebate, o.high);
      b = offer(o, 0, o.low);
      if (b.loan <= 0.005) msg = 'Your down payment and trade-in cover the full cost, so there is no loan to compare.';
    }
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) { clearResults(); return; }

    var diff = a.total - b.total, box = el('cbVerdictBox');
    if (Math.abs(diff) < 0.005) {
      setText('cbVerdictTitle', 'The two offers cost the same');
      setText('cbVerdict', 'Pick whichever has the lower monthly payment or the terms you prefer.');
      box.className = 'callout callout-note mt-4';
    } else if (diff < 0) {
      setText('cbVerdictTitle', 'Take the cash back');
      setText('cbVerdict', 'Taking the ' + money.format(o.rebate) + ' rebate and financing at ' + rateText(o.high) + ' costs ' +
        money.format(-diff) + ' less overall than the ' + rateText(o.low) + ' promotional rate.');
      box.className = 'callout callout-success mt-4';
    } else {
      setText('cbVerdictTitle', 'Take the low interest rate');
      setText('cbVerdict', 'The ' + rateText(o.low) + ' rate saves ' + money.format(Math.max(0, a.interest - b.interest)) +
        ' in interest, which outweighs the ' + money.format(o.rebate) + ' rebate. Overall it costs ' + money.format(diff) + ' less.');
      box.className = 'callout callout-success mt-4';
    }
    setText('cbSaving', money.format(Math.abs(diff)));
    var be = breakEven(o);
    setText('cbBreakEven', isNaN(be) ? 'None' : be === Infinity ? 'Above 100%' : be.toFixed(2) + '%');

    var rows = [
      ['Amount financed', a.loan, b.loan], ['Interest rate', null, null], ['Monthly payment', a.pmt, b.pmt],
      ['Total interest', a.interest, b.interest], ['Sales tax', a.tax, b.tax], ['Due at purchase', a.upfront, b.upfront],
      ['Total of loan payments', a.paid, b.paid], ['Total cost of the vehicle', a.total, b.total]
    ];
    el('cbTable').innerHTML = rows.map(function (row) {
      var c1 = row[1] === null ? o.high.toFixed(2) + '%' : money.format(row[1]);
      var c2 = row[2] === null ? o.low.toFixed(2) + '%' : money.format(row[2]);
      return '<tr><th scope="row">' + row[0] + '</th><td>' + c1 + '</td><td>' + c2 + '</td></tr>';
    }).join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('cbForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
